CREATE TABLE transaction_log (log_id SERIAL PRIMARY KEY, member_reg BIGINT, member_fan_pivot TEXT, memb_kind TEXT, spend_usd REAL, trans_date DATE DEFAULT CURRENT_DATE);

INSERT INTO transaction_log (member_reg, member_fan_pivot, memb_kind, spend_usd)
SELECT m.member_reg, m.member_fan_pivot, m.memb_kind, m.spend_usd
FROM membershipandspending m
JOIN fans f ON m.member_fan_pivot = f.user_registry
WHERE f.reg_moment < DATE_TRUNC('year', CURRENT_DATE)::text - INTERVAL '1' YEAR;

SELECT COUNT(*) FROM transaction_log;

